public class CT_PageBlock extends OFDElement implements PageBlockType {
    public CT_PageBlock(Element proxy) {
        super(proxy);
    }

    protected CT_PageBlock(String name) {
        super(name);
    }

    public CT_PageBlock() {
        this("PageBlock");
    }


    /**
     * 【可选】
     * 增加 页块
     * <p>
     * 一个页块中可以嵌套其他页块，可含有0到多个页块
     *
     * @param pageBlock 页块实例
     * @return this
     */
    public CT_PageBlock addPageBlock(PageBlockType pageBlock) {
        this.add(pageBlock);
        return this;
    }

    /**
     * 【可选】
     * 获取 当前页块内的所有页块
     * <p>
     * 一个页块中可以嵌套其他页块，可含有0到多个页块
     * <p>
     * Tip： 从列表取出的元素可以使用<code>instanceof</code> 判断元素的类型
     *
     * @return 当前页块内的所有页块
     */
    public List<PageBlockType> getPageBlocks() {
        List<Element> elements = this.elements();
        List<PageBlockType> res = new ArrayList<>(elements.size());
        for (Element element : elements) {
            PageBlockType pb = PageBlockType.getInstance(element);
            if (pb != null){
                res.add(pb);
            }
        }
        return res;
    }


}

public class Paragraph extends Div<Paragraph> {

    /**
     * 首行缩进字符数
     * <p>
     * null 标识没有缩进
     */
    private Integer firstLineIndent = null;

    /**
     * 首行缩进数值
     * 单位：mm
     */
    private Double firstLineIndentWidth = null;

    /**
     * 行间距
     */
    private Double lineSpace = 2d;

    /**
     * 默认字体
     */
    private Font defaultFont;

    /**
     * 默认字号
     */
    private Double defaultFontSize;

    /**
     * 文字内容
     */
    private LinkedList<Span> contents;

    /**
     * 元素内行缓存
     */
    private LinkedList<TxtLineBlock> lines;

    /**
     * 字体在段落内的浮动方向
     * <p>
     * 默认为：左浮动
     */
    private TextAlign textAlign = TextAlign.left;

    /**
     * 创建一个固定大小段落对象
     *
     * @param width  内容宽度
     * @param height 内容高度
     */
    public Paragraph(Double width, Double height) {
        this();
        setWidth(width).setHeight(height);
    }

    /**
     * 创建一个段落对象
     * <p>
     * 注意如果不主动对 Paragraph 设置宽度，那么Paragraph
     * 会独占整个段，并且与段具有相同宽度，也就是页面宽度，
     * 在需要更加细致盒式的布局时 请设置{@link #setClear(Clear)}
     * 并设置段落宽度 {@link #setWidth(Double)}。
     */
    public Paragraph() {
        this.setClear(Clear.both);
        this.contents = new LinkedList<>();
        this.lines = new LinkedList<>();
    }

    /**
     * 创建绝对定位段落对象
     *
     * @param x      固定布局的盒式模型左上角X坐标
     * @param y      固定布局的盒式模型左上角y坐标
     * @param width  宽度
     * @param height 高度
     */
    public Paragraph(double x, double y, double width, double height) {
        super(x, y, width, height);
        this.contents = new LinkedList<>();
        this.lines = new LinkedList<>();
    }

    /**
     * 创建绝对定位段落对象
     *
     * @param x        固定布局的盒式模型左上角X坐标
     * @param y        固定布局的盒式模型左上角y坐标
     * @param width    宽度
     * @param height   高度
     * @param text     文本内容
     * @param fontSize 字号
     */
    public Paragraph(double x, double y, double width, double height, String text, double fontSize) {
        super(x, y, width, height);
        if (text == null) {
            throw new IllegalArgumentException("文字内容为null");
        }
        this.contents = new LinkedList<>();
        this.lines = new LinkedList<>();

        this.setFontSize(fontSize);
        this.add(text);
    }


    /**
     * 新建一个段落对象
     * <p>
     * 如果在指定段落中文字大小建议使用{@link Paragraph#Paragraph(java.lang.String, java.lang.Double)}
     *
     * @param text 文字内容
     */
    public Paragraph(String text) {
        this();
        if (text == null) {
            throw new IllegalArgumentException("文字内容为null");
        }
        this.add(text);
    }

    /**
     * 新建一个段落对象，并指定文字大小
     *
     * @param text            文字内容
     * @param defaultFontSize 默认字体大小。
     */
    public Paragraph(String text, Double defaultFontSize) {
        this();
        if (text == null) {
            throw new IllegalArgumentException("文字内容为null");
        }
        this.setFontSize(defaultFontSize);
        this.add(text);
    }

    /**
     * 新建一个段落对象，并指定文字大小和字体
     *
     * @param text            文字内容
     * @param defaultFontSize 默认字体大小
     * @param defaultFont     默认字体
     */
    public Paragraph(String text, Double defaultFontSize, Font defaultFont) {
        this();
        if (text == null) {
            throw new IllegalArgumentException("文字内容为null");
        }
        this.setFontSize(defaultFontSize);
        this.setDefaultFont(defaultFont);
        this.add(text);
    }

    /**
     * 新建一个段落对象，并指定字体
     *
     * @param text        文字内容
     * @param defaultFont 默认字体
     */
    public Paragraph(String text, Font defaultFont) {
        this();
        if (text == null) {
            throw new IllegalArgumentException("文字内容为null");
        }
        this.setDefaultFont(defaultFont);
        this.add(text);
    }

    /**
     * 增加段落中的文字
     * <p>
     * 文字样式使用span默认字体样式
     *
     * @param text 文本内容
     * @return this
     */
    public Paragraph add(String text) {
        if (text == null) {
            return this;
        }
        Span newTxt = new Span(text);
        if (this.defaultFont != null) {
            newTxt.setFont(defaultFont);
        }
        if (this.defaultFontSize != null) {
            newTxt.setFontSize(defaultFontSize);
        }
        return this.add(newTxt);
    }

    /**
     * 加入带有特殊样式文字内容
     *
     * @param content 特殊样式文字内容
     * @return this
     */
    public Paragraph add(Span content) {
        if (content == null) {
            return this;
        }
        this.contents.add(content);
        return this;
    }

    public Double getLineSpace() {
        return lineSpace;
    }

    public Paragraph setLineSpace(Double lineSpace) {
        this.lineSpace = lineSpace;
        return this;
    }

