package org.ofdrw.layout.engine.render;

import org.junit.jupiter.api.Test;
import org.ofdrw.core.basicStructure.pageObj.layer.block.CT_PageBlock;
import org.ofdrw.layout.element.Paragraph;

import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.jupiter.api.Assertions.assertEquals;

public class ParagraphRenderRenderTests {

    @Test
    void renderDoesNotModifyLayerOrIdForEmptyParagraph() {
        CT_PageBlock layer = new CT_PageBlock();
        Paragraph paragraph = new Paragraph(0d, 0d, 100d, 100d);
        AtomicInteger maxUnitId = new AtomicInteger(7);

        ParagraphRender.render(layer, null, paragraph, maxUnitId);

        assertEquals(0, layer.getPageBlocks().size());
        assertEquals(7, maxUnitId.get());
    }

    @Test
    void renderReturnsImmediatelyForNullParagraph() {
        CT_PageBlock layer = new CT_PageBlock();
        AtomicInteger maxUnitId = new AtomicInteger(11);

        ParagraphRender.render(layer, null, null, maxUnitId);

        assertEquals(0, layer.getPageBlocks().size());
        assertEquals(11, maxUnitId.get());
    }
}

