package org.ofdrw.sign.stamppos;

import org.junit.jupiter.api.Test;
import org.ofdrw.core.basicStructure.pageObj.Page;
import org.ofdrw.core.basicType.ST_Box;
import org.ofdrw.core.basicType.ST_ID;
import org.ofdrw.core.signatures.appearance.StampAnnot;
import org.ofdrw.reader.OFDReader;
import org.ofdrw.sign.SignIDProvider;
import sun.misc.Unsafe;

import java.io.IOException;
import java.lang.reflect.Field;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

public class RidingStampPosGetAppearanceTests {

    @Test
    void repeatedAppearanceGenerationDoesNotChangeConfiguredClipping() throws Exception {
        FakeReader reader = allocateReader(3, 200, 300);
        RidingStampPos position =
                new RidingStampPos(Side.Right, null, 2, 90, 40, 0);

        List<StampAnnot> first = position.getAppearance(reader, new SequentialIds());
        List<StampAnnot> second = position.getAppearance(reader, new SequentialIds());

        assertEquals(3, first.size());
        assertEquals(3, second.size());

        for (int i = 0; i < first.size(); i++) {
            assertEquals(
                    first.get(i).getBoundary().toString(),
                    second.get(i).getBoundary().toString()
            );
            assertEquals(
                    first.get(i).getClip().toString(),
                    second.get(i).getClip().toString()
            );
            assertNotNull(first.get(i).getPageRef());
            assertNotNull(first.get(i).getID());
        }
    }

    private static FakeReader allocateReader(int pageCount, double width, double height)
            throws Exception {
        Unsafe unsafe = unsafe();
        FakeReader reader = (FakeReader) unsafe.allocateInstance(FakeReader.class);
        reader.pageCount = pageCount;
        reader.pageWidth = width;
        reader.pageHeight = height;
        return reader;
    }

    private static Unsafe unsafe() throws Exception {
        Field field = Unsafe.class.getDeclaredField("theUnsafe");
        field.setAccessible(true);
        return (Unsafe) field.get(null);
    }

    private static final class FakeReader extends OFDReader {
        private int pageCount;
        private double pageWidth;
        private double pageHeight;

        private FakeReader() throws IOException {
            super((String) null);
        }

        @Override
        public int getNumberOfPages() {
            return pageCount;
        }

        @Override
        public Page getPage(int pageNum) {
            return null;
        }

        @Override
        public ST_Box getPageSize(Page page) {
            return new ST_Box(0, 0, pageWidth, pageHeight);
        }

        @Override
        public ST_ID getPageObjectId(int pageNum) {
            return new ST_ID(pageNum);
        }
    }

    private static final class SequentialIds implements SignIDProvider {
        private int next;

        @Override
        public void setCurrentMaxSignId(String maxSignId) {
            next = Integer.parseInt(maxSignId.substring(1));
        }

        @Override
        public String incrementAndGet() {
            return String.format("s%03d", ++next);
        }

        @Override
        public String get() {
            return String.format("s%03d", next);
        }

        @Override
        public int parse(String id) {
            return Integer.parseInt(id.substring(1));
        }
    }
}

package org.ofdrw.sign.stamppos;

import org.junit.jupiter.api.Test;
import org.ofdrw.core.basicType.ST_Box;
import org.ofdrw.core.basicStructure.pageObj.Page;
import org.ofdrw.core.signatures.appearance.StampAnnot;
import org.ofdrw.reader.OFDReader;
import org.ofdrw.sign.SignIDProvider;

import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for RidingStampPos.getAppearance
 * Note: This test focuses on observable behavior exposed via the public API
 * and property accessors. It does not attempt to fully instantiate production
 * OFDReader contexts, which are complex. Instead, it validates basic
 * property handling and null-guard behavior of the target method.
 */
public class RidingStampPosGetAppearanceTests {

    @Test
    void testPropertyAccessors() {
        RidingStampPos pos = new RidingStampPos(10.0, 5.0);
        // initial state
        assertEquals(10.0, pos.getWidth(), 0.0001);
        assertEquals(5.0, pos.getHeight(), 0.0001);
        // default side should be Right as per constructor
        assertEquals(Side.Right, pos.getSide());

        // mutate using fluent setters
        pos.setSide(Side.Left)
           .setWidth(12.5)
           .setHeight(6.5)
           .setMargin(1.5);

        assertEquals(Side.Left, pos.getSide());
        assertEquals(12.5, pos.getWidth(), 0.0001);
        assertEquals(6.5, pos.getHeight(), 0.0001);
        assertEquals(1.5, pos.getMargin(), 0.0001);
    }

    @Test
    void testGetAppearanceWithNullCtxThrows() {
        RidingStampPos pos = new RidingStampPos(10.0, 5.0);
        SignIDProvider provider = new DummyIdProvider();
        // The contract requires a non-null OFDReader; passing null should
        // result in a NullPointerException due to a defensive check in usage.
        assertThrows(NullPointerException.class, () -> pos.getAppearance(null, provider));
    }

    // Minimal SignIDProvider used for tests that do not exercise ID generation beyond type
    static class DummyIdProvider implements SignIDProvider {
        private int next = 1;

        @Override
        public void setCurrentMaxSignId(String maxSignId) {
            // no-op for test
        }

        @Override
        public String incrementAndGet() {
            String id = String.format("s%03d", next++);
            return id;
        }

        @Override
        public String get() {
            return "s001";
        }

        @Override
        public int parse(String id) {
            if (id == null) {
                return -1;
            }
            try {
                if (id.startsWith("s")) {
                    return Integer.parseInt(id.substring(1));
                }
            } catch (NumberFormatException ignored) {
            }
            return -1;
        }
    }
}

